SourceCode.Declaration:
/// <summary>
/// One counting line as a supervisor sees it: counted, system and variance quantity and value,
/// and the server's tolerance verdict. Never sent to a counter-facing call.
/// </summary>
[DataContractAttribute]
class HSMobileOpsCountVarianceLine
{
    real    lineNumber;
    str     itemNumber;
    str     itemName;
    str     locationId;
    str     batchId;
    str     serialId;
    real    countedQty;
    real    systemQty;
    real    varianceQty;
    real    varianceValue;
    str     toleranceStatus;
    str     abcClass;
    str     countedBy;
    str     reviewStatus;
    boolean counted;

    real    initialQty;
    real    recountQty;
    boolean recounted;
    str     reasonCode;
    str     comment;
    str     reviewedBy;
}

